"""Documentation generator — README, architecture, API, database, deployment docs."""
from __future__ import annotations

from typing import Any


def render_readme(spec: dict[str, Any], stack: dict[str, Any]) -> str:
    features = "\n".join(f"- {feat}" for feat in spec.get("features", []))
    roles = ", ".join(spec.get("users", []))
    return f'''# {spec["name"]}

**{spec.get("app_type", "Web Application")}** — generated by [QuantBuild], an AI-powered
full-stack architecture designer and application builder.

## Overview

{spec.get("summary", "")}

## Features

{features}

## User Roles

{roles}

## Tech Stack

| Layer | Technology |
| --- | --- |
| Frontend | {stack.get("frontend", {}).get("framework", "React")} + {stack.get("frontend", {}).get("language", "TypeScript")} + {stack.get("frontend", {}).get("styling", "Tailwind CSS")} |
| Backend | {stack.get("backend", {}).get("framework", "FastAPI")} + {stack.get("backend", {}).get("orm", "SQLAlchemy")} |
| Database | {stack.get("database", {}).get("development", "SQLite")} (dev) / {stack.get("database", {}).get("production", "PostgreSQL")} (prod) |
| Auth | {spec.get("security", {}).get("authentication", "JWT")} with {spec.get("security", {}).get("authorization", "RBAC")} |
| Testing | {stack.get("testing", {}).get("backend", "pytest")} |
| Deployment | {stack.get("deployment", {}).get("containers", "Docker")} + {stack.get("deployment", {}).get("orchestration", "Docker Compose")} |

## Project Structure

```
backend/     FastAPI application (routers, services, models, security)
frontend/    React + TypeScript SPA
docs/        Architecture, API, database and deployment documentation
migrations/  SQL schema migrations
```

## Quick Start

### Backend

```bash
cd backend
python -m venv .venv && source .venv/bin/activate   # Windows: .venv\\Scripts\\activate
pip install -r requirements.txt
python -m app.seed                                   # demo data (admin@example.com / Admin1234)
uvicorn app.main:app --reload --port 8000
```

### Frontend

```bash
cd frontend
npm install
npm run dev                                          # http://localhost:5173
```

### Tests

```bash
cd backend
python -m pytest tests -q
```

### Docker

```bash
docker compose up --build
```

## Environment Variables

See `.env.example`.

## Documentation

- [Architecture](docs/ARCHITECTURE.md)
- [API reference](docs/API.md)
- [Database design](docs/DATABASE.md)
- [Deployment guide](docs/DEPLOYMENT.md)
'''


def render_architecture_doc(spec: dict[str, Any], arch: dict[str, Any]) -> str:
    layers = "\n".join(
        f"| {layer['name']} | {layer['technology']} | {layer['responsibility']} |"
        for layer in arch.get("layers", []))
    components = "\n".join(
        f"- **{c['name']}** ({c['kind']}): {c['description']}"
        for c in arch.get("components", []))
    return f'''# Architecture — {spec["name"]}

## Style: {arch.get("style", "Modular Monolith")}

{arch.get("rationale", "")}

## System Diagram

```mermaid
{arch.get("diagram", "")}
```

## Layers

| Layer | Technology | Responsibility |
| --- | --- | --- |
{layers}

## Components

{components}

## Communication

{arch.get("communication", "REST/JSON over HTTPS")}

## Deployment Topology

{arch.get("deployment_topology", "")}
'''


def render_api_doc(spec: dict[str, Any], api_contract: dict[str, Any]) -> str:
    lines = [f"# API Reference — {spec['name']}", "",
             "Base URL: `/api` — all endpoints (except auth) require "
             "`Authorization: Bearer <token>`.", ""]
    current_resource = None
    for ep in api_contract.get("endpoints", []):
        if ep["resource"] != current_resource:
            current_resource = ep["resource"]
            lines += ["", f"## {current_resource}", ""]
        lines.append(f"- `{ep['method']} {ep['path']}` — {ep['summary']}")
    lines += ["", "## Errors", "",
              "| Status | Meaning |", "| --- | --- |",
              "| 400 | Bad request |", "| 401 | Missing/invalid token |",
              "| 403 | Insufficient permissions or ownership |",
              "| 404 | Resource not found |", "| 409 | Uniqueness conflict |",
              "| 422 | Validation error |", "| 429 | Rate limited |", ""]
    return "\n".join(lines)


def render_database_doc(spec: dict[str, Any], schema: dict[str, Any]) -> str:
    entity_sections = []
    for ent in schema.get("entities", []):
        rows = "\n".join(
            f"| {fld['name']} | {fld['type']} | "
            f"{'PK' if fld.get('primary_key') else ('FK→' + fld.get('ref', '')) if fld['type'] == 'fk' else ''} | "
            f"{'yes' if fld.get('nullable') else 'no'} | "
            f"{'yes' if fld.get('unique') else 'no'} |"
            for fld in ent["fields"])
        entity_sections.append(f"""### {ent['name']} (`{ent['table']}`)

{ent.get('description', '')}

| Field | Type | Key | Nullable | Unique |
| --- | --- | --- | --- | --- |
{rows}
""")
    rels = "\n".join(f"- {r['description']} ({r['type']})"
                     for r in schema.get("relationships", []))
    idx = "\n".join(f"- `{i}`" for i in schema.get("indexes", []))
    return f"""# Database Design — {spec['name']}

## ER Diagram

```mermaid
{schema.get("er_diagram", "")}
```

## Tables

{chr(10).join(entity_sections)}

## Relationships

{rels or "- None"}

## Indexes & Constraints

{idx or "- Primary keys only"}

## Migration

`migrations/0001_init.sql` contains the complete DDL.
"""


def render_deployment_doc(spec: dict[str, Any]) -> str:
    return f'''# Deployment Guide — {spec["name"]}

## Prerequisites

- Docker & Docker Compose (recommended), or Python 3.11+ and Node 20+

## Configuration

Copy `.env.example` to `.env` and set:

| Variable | Purpose |
| --- | --- |
| `SECRET_KEY` | JWT signing secret (**must** be set in production) |
| `DATABASE_URL` | SQLAlchemy connection string |
| `CORS_ORIGINS` | Allowed frontend origins (comma-separated) |
| `TOKEN_TTL_SECONDS` | JWT lifetime |
| `AUTH_RATE_LIMIT` | Auth requests per minute per IP |

## Docker Compose (recommended)

```bash
docker compose up --build
```

- API: http://localhost:8000 (docs at `/docs`)
- Frontend: http://localhost:5173

## Manual

1. Backend: `cd backend && pip install -r requirements.txt && uvicorn app.main:app`
2. Frontend: `cd frontend && npm install && npm run build` and serve `dist/`
   behind any static file server or reverse proxy.

## Production Checklist

- [ ] Strong `SECRET_KEY` set via environment/secret manager
- [ ] PostgreSQL `DATABASE_URL` configured
- [ ] HTTPS terminated at the load balancer / reverse proxy
- [ ] CORS restricted to the real frontend origin
- [ ] CI pipeline green (`.github/workflows/ci.yml`)
'''


def render_env_example(spec: dict[str, Any]) -> str:
    return ('APP_NAME="' + spec["name"] + '"\n'
            "SECRET_KEY=change-me-to-a-long-random-string\n"
            "DATABASE_URL=sqlite:///./app.db\n"
            "TOKEN_TTL_SECONDS=3600\n"
            "CORS_ORIGINS=http://localhost:5173\n"
            "AUTH_RATE_LIMIT=30\n")
